    // specified. Useful for downloading just a part of an object.
    part_number: Int? = None,
    // The account ID of the expected bucket owner. If the account ID that you
    // provide does not match the actual owner of the bucket, the request fails
    // with the HTTP status code 403 Forbidden (access denied).
    expected_bucket_owner: Str? = None,
    // To retrieve the checksum, this mode must be enabled.
    checksum_mode: ChecksumMode? = None
}

// Not mapped: `expires` — the SDKs customize it away from the model
// (`omitMembers` in smithy-build.json).
// Linear, because it holds a stream: take the stream out (`let {body} = value`)
// and close it when done, or give the whole value up with [close]
// [linear-group].
export linear struct GetObjectOutput {
    // Object data.
    body: InStream,
    // Indicates whether the object retrieved was (true) or was not (false) a
    // Delete Marker. If false, this response header does not appear in the
    // response.
    delete_marker: Bool? = None,
    // Indicates that a range of bytes was specified in the request.
    accept_ranges: Str? = None,
    // If the object expiration is configured (see
    // PutBucketLifecycleConfiguration), the response includes this header. It
    // includes the expiry-date and rule-id key-value pairs providing object
    // expiration information. The value of the rule-id is URL-encoded.
    expiration: Str? = None,
    // Provides information about object restoration action and expiration time
    // of the restored object copy.
    restore: Str? = None,
    // Date and time when the object was last modified.
    last_modified: Instant? = None,
    // Size of the body in bytes.
    content_length: Long? = None,
    // An entity tag (ETag) is an opaque identifier assigned by a web server to
    // a specific version of a resource found at a URL.
    e_tag: Str? = None,
    // The Base64 encoded, 32-bit CRC32 checksum of the object. This checksum is
    // only present if the checksum was uploaded with the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_crc32: Str? = None,
    // The Base64 encoded, 32-bit CRC32C checksum of the object. This checksum
    // is only present if the checksum was uploaded with the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_crc32_c: Str? = None,
    // The Base64 encoded, 64-bit CRC64NVME checksum of the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_crc64_nvme: Str? = None,
    // The Base64 encoded, 160-bit SHA1 digest of the object. This checksum is
    // only present if the checksum was uploaded with the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_sha1: Str? = None,
    // The Base64 encoded, 256-bit SHA256 digest of the object. This checksum is
    // only present if the checksum was uploaded with the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_sha256: Str? = None,
    // The Base64 encoded, 512-bit SHA512 digest of the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_sha512: Str? = None,
    // The Base64 encoded, 128-bit MD5 digest of the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_md5: Str? = None,
    // The Base64 encoded, 64-bit XXHASH64 checksum of the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_xxhash64: Str? = None,
    // The Base64 encoded, 64-bit XXHASH3 checksum of the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_xxhash3: Str? = None,
    // The Base64 encoded, 128-bit XXHASH128 checksum of the object. For more
    // information, see Checking object integrity in the Amazon S3 User Guide.
    checksum_xxhash128: Str? = None,
    // The checksum type, which determines how part-level checksums are combined
    // to create an object-level checksum for multipart objects. You can use
    // this header response to verify that the checksum type that is received is
    // the same checksum type that was specified in the CreateMultipartUpload
    // request. For more information, see Checking object integrity in the
    // Amazon S3 User Guide.
    checksum_type: ChecksumType? = None,
    // This is set to the number of metadata entries not returned in the headers
    // that are prefixed with x-amz-meta-. This can happen if you create
    // metadata using an API like SOAP that supports more flexible metadata than
    // the REST API. For example, using SOAP, you can create metadata whose
    // values are not legal HTTP headers.
    missing_meta: Int? = None,
    // Version ID of the object.
    version_id: Str? = None,
    // Specifies caching behavior along the request/reply chain.
    cache_control: Str? = None,
    // Specifies presentational information for the object.
    content_disposition: Str? = None,
    // Indicates what content encodings have been applied to the object and thus
    // what decoding mechanisms must be applied to obtain the media-type
    // referenced by the Content-Type header field.
    content_encoding: Str? = None,
    // The language the content is in.
    content_language: Str? = None,
    // The portion of the object returned in the response.
    content_range: Str? = None,
    // A standard MIME type describing the format of the object data.
    content_type: Str? = None,
    // If the bucket is configured as a website, redirects requests for this
    // object to another object in the same bucket or to an external URL. Amazon
    // S3 stores the value of this header in the object metadata.
    website_redirect_location: Str? = None,
    // The server-side encryption algorithm used when you store this object in
    // Amazon S3 or Amazon FSx.
    server_side_encryption: ServerSideEncryption? = None,
    // A map of metadata to store with the object in S3.
    metadata: Map<Str, Str>? = None,
    // If server-side encryption with a customer-provided encryption key was
    // requested, the response will include this header to confirm the
    // encryption algorithm that's used.
    sse_customer_algorithm: Str? = None,
    // If server-side encryption with a customer-provided encryption key was
    // requested, the response will include this header to provide the
    // round-trip message integrity verification of the customer-provided
    // encryption key.
    sse_customer_key_md5: Str? = None,
    // If present, indicates the ID of the KMS key that was used for object
    // encryption.
    ssekms_key_id: Str? = None,
    // Indicates whether the object uses an S3 Bucket Key for server-side
    // encryption with Key Management Service (KMS) keys (SSE-KMS).
    bucket_key_enabled: Bool? = None,
    // Provides storage class information of the object. Amazon S3 returns this
    // header for all objects except for S3 Standard storage class objects.
    storage_class: StorageClass? = None,
    request_charged: RequestCharged? = None,
    // Amazon S3 can return this if your request involves a bucket that is
    // either a source or destination in a replication rule.
    replication_status: ReplicationStatus? = None,
    // The count of parts this object has. This value is only returned if you
    // specify partNumber in your request and the object was uploaded as a
    // multipart upload.
    parts_count: Int? = None,
    // The number of tags, if any, on the object, when you have the relevant
    // permission to read object tags.
    tag_count: Int? = None,
    // The Object Lock mode that's currently in place for this object.
    object_lock_mode: ObjectLockMode? = None,
    // The date and time when this object's Object Lock will expire.
    object_lock_retain_until_date: Instant? = None,
    // Indicates whether this object has an active legal hold. This field is
    // only returned if you have permission to view an object's legal hold
    // status.
    object_lock_legal_hold_status: ObjectLockLegalHoldStatus? = None,
    // The event hold status for this object. This header is only returned if
    // the requester has the s3:GetObjectRetention permission.
    object_lock_event_hold: ObjectLockEventHold? = None,
    // The event hold duration in days for this object. Only returned when the
    // event hold is enabled.
    object_lock_event_hold_duration_days: Int? = None,
    // The event hold duration in years for this object. Only returned when the
    // event hold is enabled.
    object_lock_event_hold_duration_years: Int? = None
}

// Gives up [value] without reading its body: the stream is closed and the other
// members are dropped. The discharger of [GetObjectOutput] [linear-group].
export fn close(value: GetObjectOutput) [Streams] -> Ok None | Err Checked<StreamError> => !value {
    return close(value.body)
}

// A code S3 answers with: one arm per error the model names for these
// operations, and `Other` for anything else the service sends — throttling, an
// authorization failure, a code newer than this model. A legacy wire code is
// normalized to the model's name, so a code reads the same on every backend.
export type S3ErrorCode = "EncryptionTypeMismatch"
    | "InvalidObjectState"
    | "InvalidRequest"
    | "InvalidWriteOffset"
    | "NoSuchKey"
    | "TooManyParts"
    | Other Str

// The service answered with an error: what it said, and the HTTP status it said
// it with.
export struct S3Error {
    code: S3ErrorCode,
    message: Str,
    // The HTTP status of the response.
    status: Int,
    // The service's id for the request, when it sent one: what AWS support asks for.
    request_id: Str? = None,
    // Set for `InvalidObjectState` only.
    storage_class: StorageClass? = None,
    // Set for `InvalidObjectState` only.
    access_tier: IntelligentTieringAccessTier? = None
}

// Everything an operation of [S3] can answer with instead of its output: the
// service's error, or an [AwsError] when there was no answer to read.
export type S3Failure = S3Error | AwsError

// Amazon Simple Storage Service. Every member hands its [reply] to the provider
// and returns at once; the answer is the operation's output or a `Checked`
// [S3Failure].
export effect S3 {
    // Adds an object to a bucket.
    fn put_object(input: PutObjectInput, reply: Reply<Ok PutObjectOutput | Err Checked<S3Failure>>) -> None
    => !input, !reply

    // Retrieves an object from Amazon S3.
    fn get_object(input: GetObjectInput, reply: Reply<Ok GetObjectOutput | Err Checked<S3Failure>>) -> None
    => !input, !reply
}

// What a [FakeS3] was asked, in order: one operation name per call.
export effect S3Calls {
    // The names of the operations called so far (`put_object`, …).
    fn calls() -> List<Str>
}

// A recording double for [S3]: every call is noted by operation name — read
// them through [S3Calls] — and answered with an empty output where the
// operation's output has no required members, otherwise with `AwsError { code:
// "NotStubbed" }`. A body it is handed is closed unread, and a body it answers
// with is empty, minted in the `Streams` in scope. A test that needs real
// answers implements [S3] itself.
export handler FakeS3() [Streams] of S3, S3Calls {
    recorded: Mut List<Str> = mut_list_of()

    fn put_object(input: PutObjectInput, reply: Reply<Ok PutObjectOutput | Err Checked<S3Failure>>) -> None => !input, !reply {
        recorded.add("put_object")
        let unsized = input.content_length is None
        let closed = close(input)
        if closed is Err {
            ignore(closed)
        }
        if unsized {
            reply.send(err(checked<S3Failure>(AwsError { code: "MissingContentLength", message: "S3 PutObject streams its body, so the input needs content_length: the body's length in bytes" })))
            return None
        }
        reply.send(ok(PutObjectOutput {}))
    }

    fn get_object(input: GetObjectInput, reply: Reply<Ok GetObjectOutput | Err Checked<S3Failure>>) -> None => !input, !reply {
        recorded.add("get_object")
        reply.send(ok(GetObjectOutput { body: from_bytes(bytes_of()) }))
    }

    fn calls() -> List<Str> {
        return copy(recorded)
    }
}
